<?php
require_once dirname(__DIR__).'/includes/bootstrap.php';club_require_capability('content.publish');$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    csrf_verify();try{club_content_moderate((string)($_POST['kind']??''),(int)($_POST['id']??0),(string)($_POST['action']??''),(string)($_POST['reviewer_note']??''),!empty($_POST['revision_id'])?(int)$_POST['revision_id']:null,(string)($_POST['review_hash']??''));flash_success('The decision has been saved.');redirect('/admin/submissions.php');}catch(Throwable $e){$error=$e->getMessage();}
}
// Keep the visible preview and its fingerprint on one database snapshot.
$ownsReadTransaction=!db()->inTransaction();if($ownsReadTransaction)db()->beginTransaction();
$queue=[];foreach(['post'=>'club_posts','event'=>'events'] as $kind=>$table){$s=db()->query("SELECT c.*,u.full_name FROM $table c LEFT JOIN club_users u ON u.id=c.author_user_id WHERE c.status='submitted'".($kind==='event'?' AND c.deleted_at IS NULL':'')." ORDER BY c.created_at");foreach($s->fetchAll() as $row)$queue[]=['kind'=>$kind,'row'=>$row,'revision'=>null];}
$s=db()->query("SELECT r.*,u.full_name FROM club_revisions r JOIN club_users u ON u.id=r.author_user_id WHERE r.status='submitted' AND r.owner_type IN('post','event') ORDER BY r.created_at");foreach($s->fetchAll() as $revision){$row=club_community_record($revision['owner_type'],(int)$revision['owner_id']);if($row&&$row['status']==='published')$queue[]=['kind'=>$revision['owner_type'],'row'=>array_merge($row,json_decode($revision['payload'],true),['full_name'=>$revision['full_name']]),'revision'=>$revision];}
club_member_layout_start('Review submissions');flash_render();
?>
<p>Check the details and attachments before publishing. Approving a post also queues it for Facebook and Instagram. Sharing starts once the club accounts are connected. Events are published to the calendar only.</p><?php if($error): ?><p class="alert alert--error" role="alert"><?= e($error) ?></p><?php endif ?><?php if(!$queue): ?><div class="platform-panel empty-state"><h2>All caught up</h2><p>New posts, events and revisions will appear here for review.</p></div><?php endif ?>
<?php foreach($queue as $entry):$row=$entry['row'];$kind=$entry['kind'];$revision=$entry['revision'];
$reviewFiles=$kind==='post'?club_attachment_list('post',(int)$row['id']):[];
if($kind==='post'&&$revision)$reviewFiles=array_merge($reviewFiles,club_attachment_list('revision',(int)$revision['id']));
$reviewRemoved=$kind==='post'?array_map('intval',$row['removed_attachment_ids']??[]):[];
$reviewFiles=array_values(array_filter($reviewFiles,fn($file)=>!in_array((int)$file['id'],$reviewRemoved,true)));
$reviewImages=array_map('intval',array_column(array_filter($reviewFiles,fn($a)=>str_starts_with($a['mime'],'image/')),'id'));
$reviewBody=$kind==='post'?club_editor_sanitize($row['content'],$reviewImages,false):sanitize_html($row['description']??'');
$reviewInline=$kind==='post'?club_editor_inline_ids($reviewBody):[];
$reviewCover=$kind==='post'?(int)($row['cover_attachment_id']??0):0;
?>
<article class="platform-panel"><p class="eyebrow"><?= $revision?'PROPOSED REVISION':strtoupper($kind) ?> · <?= e($row['full_name']??'Committee') ?></p><h2><?= e($row['title']) ?></h2><?php if($kind==='event'): ?><p><strong><?= e(format_date($row['event_date'])) ?></strong> · <?= empty($row['start_time'])?'All day':e(substr($row['start_time'],0,5)) ?> · <?= e($row['venue']) ?></p><p><?= $row['visibility']==='members'?'Members only — never share publicly':'Public' ?><?= $row['recurrence']!=='none'?' · Repeats '.e($row['recurrence']).' until '.e(format_date($row['recurrence_end_date'])):'' ?></p><?php if(!empty($row['booking_link'])): ?><p>Booking link: <?= e($row['booking_link']) ?></p><?php endif ?><?php endif ?><?php if($reviewCover&&in_array($reviewCover,$reviewImages,true)&&!in_array($reviewCover,$reviewInline,true)):?><img src="<?=e(club_media_url($reviewCover))?>" alt="<?=e($row['title'])?>" style="max-width:100%;max-height:400px;object-fit:contain"><?php endif;?>
<?php if($kind==='post'&&!empty($row['summary'])):?><p class="lead"><?=e($row['summary'])?></p><?php endif;?><div class="rich-content"><?=$reviewBody?></div><?php $reviewSkip=array_unique([...$reviewInline,$reviewCover,...$reviewRemoved]);if($kind==='post'){club_content_attachments('post',(int)$row['id'],$reviewSkip);if($revision)club_content_attachments('revision',(int)$revision['id'],$reviewSkip);}else club_content_attachments($revision?'revision':$kind,(int)($revision['id']??$row['id'])); ?>
<form method="post"><?php csrf_field(); ?><input type="hidden" name="review_hash" value="<?= e(club_content_review_hash($kind,(int)$row['id'],$revision?(int)$revision['id']:null)) ?>"><input type="hidden" name="kind" value="<?= $kind ?>"><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><?php if($revision): ?><input type="hidden" name="revision_id" value="<?= (int)$revision['id'] ?>"><?php endif ?><div class="form-field"><label for="note-<?= $kind ?>-<?= (int)($revision['id']??$row['id']) ?>">Feedback for the author (optional)</label><textarea id="note-<?= $kind ?>-<?= (int)($revision['id']??$row['id']) ?>" name="reviewer_note" rows="2" maxlength="2000"></textarea></div><div class="hero__actions"><button class="btn btn--primary" name="action" value="approve"><?= $revision?'Approve revision':'Approve & publish' ?></button><button class="btn btn--secondary" name="action" value="reject">Return for changes</button></div></form></article>
<?php endforeach ?>
<?php if($ownsReadTransaction)db()->commit();club_member_layout_end(); ?>
